import java.util.Scanner;

public class Main {
    static final int maxn = 510;
    static int mod;
    static int[] factorial = new int[maxn];
    static int[] inv_factorial = new int[maxn];
    static int[] inv = new int[maxn];
    static int[] f = new int[maxn];
    static int[] c = new int[maxn];
    static int[][] dpA = new int[maxn][maxn];
    static int[][] dpB = new int[maxn][maxn];

    static void precompute() {
        factorial[0] = 1;
        factorial[1] = 1;
        inv[1] = 1;
        inv_factorial[0] = 1;
        inv_factorial[1] = 1;
        for (int i = 2; i < maxn; i++) {
            factorial[i] = (int) ((1L * factorial[i - 1] * i) % mod);
            inv[i] = mod - (int) ((1L * (mod / i) * inv[mod % i]) % mod);
            inv_factorial[i] = (int) ((1L * inv_factorial[i - 1] * inv[i]) % mod);
        }
    }

    static int choose(int a, int b) {
        return (int) ((1L * factorial[a] * ((1L * inv_factorial[b] * inv_factorial[a - b]) % mod)) % mod);
    }

    static long sumPairs(int x) {
        return 1L * x * (x + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextInt();
        precompute();

        f[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                long temp1 = (1L * choose(i - 1, j) * f[j]) % mod;
                long temp2 = (1L * f[i - 1 - j]) % mod;
                f[i] = (int) ((f[i] + temp1 * temp2) % mod);

                long temp3 = (1L * (i + 1) * choose(i - 1, j)) % mod;
                long temp4 = ((1L * f[j] * c[i - 1 - j]) % mod + (1L * f[i - 1 - j] * c[j]) % mod) % mod;
                c[i] = (int) ((c[i] + temp3 * temp4) % mod);

                long temp5 = (1L * choose(i - 1, j) * (sumPairs(j) + sumPairs(i - 1 - j))) % mod;
                long temp6 = (1L * f[j] * f[i - 1 - j]) % mod;
                c[i] = (int) ((c[i] + temp5 * temp6) % mod);
            }
            f[i] = (int) ((1L * f[i] * (i + 1)) % mod);
        }

        for (int i = 0; i < maxn; i++) {
            for (int j = 0; j < maxn; j++) {
                dpA[i][j] = 0;
                dpB[i][j] = 0;
            }
        }
        dpA[0][0] = 1;

        for (int k = 1; k <= n; k++) {
            dpA[k][0] = 1;
            for (int i = 1; i <= Math.min(m, k); i++) {
                dpA[k][i] = dpA[k - 1][i];
                dpB[k][i] = dpB[k - 1][i];
                for (int j = 1; j <= i; j++) {
                    long tempA = (1L * f[j] * dpA[Math.max(k - j - 1, 0)][i - j]) % mod;
                    long tempA2 = (1L * choose(i, j)) % mod;
                    dpA[k][i] = (int) ((dpA[k][i] + tempA * tempA2) % mod);

                    long tempB1 = (1L * c[j] * dpA[Math.max(k - j - 1, 0)][i - j]) % mod;
                    long tempB2 = (1L * choose(i, j)) % mod;
                    long tempB3 = (1L * f[j] * dpB[Math.max(k - j - 1, 0)][i - j]) % mod;
                    dpB[k][i] = (int) ((dpB[k][i] + tempB1 * tempB2 + tempB3 * tempB2) % mod);
                }
            }
        }
        System.out.println(dpB[n][m]);
        sc.close();
    }
}

